import{_ as t,c as e,a,aS as o}from"./chunks/framework.BB9D2qGO.js";const u=JSON.parse('{"title":"期货","description":"","frontmatter":{},"headers":[],"relativePath":"note/knowledge/11-期货.md","filePath":"note/knowledge/11-期货.md","lastUpdated":1751637732000}'),p={name:"note/knowledge/11-期货.md"},s=o('<h1 id="期货" tabindex="-1">期货 <a class="header-anchor" href="#期货" aria-label="Permalink to &quot;期货&quot;">​</a></h1><h2 id="什么是期货" tabindex="-1">什么是期货 <a class="header-anchor" href="#什么是期货" aria-label="Permalink to &quot;什么是期货&quot;">​</a></h2><p>比如你是爆米花的老板，需要买玉米，目前是1000元/吨，你担心三个月之后涨价，卖玉米的商家也担心三个月之后降价，所以你俩就签订了一份合约， 无论三个月后涨价还是降价，都以1000元/吨的价格交易，保证金10%，这份合约就是期货。</p><p>有了这份合约，你俩都抵消的风险。这就叫做 【套期保值】</p><p>这样看上去还挺好的 是吧？但是就是由于保证金制度和双向交易，使它成为了世界上最大的合法赌场。</p><div class="tip custom-block github-alert"><p class="custom-block-title">打个比方-保证金制度</p><p></p><p>如果你拿100元买股票，假如涨了10%，你就挣了10元。</p><p>如果你拿100元买期货（1000元/吨，保证金10%），假如涨了10%，也就是涨到了1100/吨，你就挣了100元。</p><p>这就是叫做【做多】</p><p>同样是100元本金，期货的盈亏就放大了10倍，这就是资本杠杆。</p></div><div class="tip custom-block github-alert"><p class="custom-block-title">打个比方-双向交易</p><p></p><p>就是说，即使你没有玉米，你也可以卖玉米合约，假如你认为玉米会跌价，你可以用100元的保证金，先卖出去一份1000元/吨的玉米合约，等它跌到900的时候， 你再买过来交给对方，这下跌的100元就是你赚的，这就是叫做【做空】。</p></div>',7),c=[s];function l(i,r,_,n,d,h){return a(),e("div",null,c)}const k=t(p,[["render",l]]);export{u as __pageData,k as default};
